import assert from "node:assert/strict";

// Cantor Defect Genesis (CDG)
//
// B_(n,m) is generated by x_0,...,x_n and y_0,...,y_m on a pair of
// Cantor streams.  The audit works with the exact dependency frontier rather
// than enumerating the 2^(n+m+2) cylinder atoms.

function context(n, m) {
  assert(Number.isSafeInteger(n) && n >= 0);
  assert(Number.isSafeInteger(m) && m >= 0);
  return { n, m };
}

function sameContext(left, right) {
  return left.n === right.n && left.m === right.m;
}

function transition(current, symbol) {
  if (symbol === "alpha") return context(current.n + 1, current.m);
  if (symbol === "delta") return context(current.n, current.m + 1);
  if (symbol === "q") return context(current.n, Math.max(current.m, current.n));
  throw new Error(`unknown primitive ${symbol}`);
}

function runWord(start, word) {
  return word.reduce((current, symbol) => transition(current, symbol), start);
}

function localRepairDefect(current) {
  return Object.fromEntries(
    ["alpha", "delta", "q"].map((symbol) => [
      symbol,
      Number(!sameContext(transition(current, symbol), current)),
    ]),
  );
}

function counterState(current) {
  return current.n - current.m;
}

function counterTransition(value, symbol) {
  if (symbol === "alpha") return value + 1;
  if (symbol === "delta") return value - 1;
  if (symbol === "q") return Math.min(value, 0);
  throw new Error(`unknown primitive ${symbol}`);
}

function exposeCylinderContext(maxXCoordinate, maxYCoordinate) {
  assert(Number.isSafeInteger(maxXCoordinate) && maxXCoordinate >= 0);
  assert(Number.isSafeInteger(maxYCoordinate) && maxYCoordinate >= 0);
  return [
    ...Array.from({ length: maxXCoordinate }, () => "alpha"),
    ...Array.from({ length: maxYCoordinate }, () => "delta"),
  ];
}

function distinguishingSuffix(leftDepth, rightDepth) {
  assert(leftDepth < rightDepth);
  const suffix = Array.from({ length: leftDepth }, () => "delta");
  const leftAfter = runWord(context(leftDepth, 0), suffix);
  const rightAfter = runWord(context(rightDepth, 0), suffix);
  assert.deepEqual(leftAfter, context(leftDepth, leftDepth));
  assert.deepEqual(rightAfter, context(rightDepth, leftDepth));
  assert.equal(localRepairDefect(leftAfter).q, 0);
  assert.equal(localRepairDefect(rightAfter).q, 1);
  return {
    deltaCount: suffix.length,
    leftAfter,
    rightAfter,
    leftQDefect: localRepairDefect(leftAfter).q,
    rightQDefect: localRepairDefect(rightAfter).q,
  };
}

function cantorPairSeriesTailDenominator(depth) {
  // For f(x,y)=sum_i (x_i+2y_i)4^(-(i+1)), truncating both streams
  // after coordinate n has exact worst-case tail 1/4^(n+1).
  return 4n ** BigInt(depth + 1);
}

function exposeCantorPairSeriesTolerance(toleranceNumerator, toleranceDenominator) {
  assert(toleranceNumerator > 0n && toleranceDenominator > 0n);
  let depth = 0;
  while (
    toleranceDenominator
    >= toleranceNumerator * cantorPairSeriesTailDenominator(depth)
  ) depth += 1;
  const errorDenominator = cantorPairSeriesTailDenominator(depth);
  return {
    depth,
    word: exposeCylinderContext(depth, depth),
    certifiedUniformError: `1/${errorDenominator}`,
    certifiedUniformErrorApproximation: 1 / Number(errorDenominator),
    errorDenominator,
  };
}

function xorRepair(bits) {
  assert.equal(bits.x.length, bits.y.length);
  return {
    x: bits.x.map((bit, index) => bit ^ bits.y[index]),
    y: [...bits.y],
  };
}

function qJoinSignature(n, m, xBits, yBits) {
  return [
    ...xBits.slice(0, n + 1),
    ...yBits.slice(0, m + 1),
    ...xBits.slice(0, n + 1).map((bit, index) => bit ^ yBits[index]),
    ...yBits.slice(0, m + 1),
  ].join("");
}

function assignmentBits(mask, offset, length) {
  return Array.from({ length }, (_, index) => (mask >> (offset + index)) & 1);
}

const root = context(0, 0);
const finiteAuditDepth = 64;

for (let n = 0; n <= finiteAuditDepth; n += 1) {
  for (let m = 0; m <= finiteAuditDepth; m += 1) {
    const current = context(n, m);
    assert.deepEqual(transition(current, "alpha"), context(n + 1, m));
    assert.deepEqual(transition(current, "delta"), context(n, m + 1));
    assert.deepEqual(transition(current, "q"), context(n, Math.max(m, n)));
    assert.deepEqual(localRepairDefect(current), {
      alpha: 1,
      delta: 1,
      q: Number(n > m),
    });
    for (const symbol of ["alpha", "delta", "q"]) {
      assert.equal(
        counterState(transition(current, symbol)),
        counterTransition(counterState(current), symbol),
      );
    }

    const exposureWord = exposeCylinderContext(n, m);
    assert.deepEqual(runWord(root, exposureWord), current);
  }
}

// D_q(x,y)=(x XOR y,y) is an involutive homeomorphism.  Exhaust all pairs of
// four-bit words as a finite truth-table audit of the algebraic identity.
for (let xMask = 0; xMask < 16; xMask += 1) {
  for (let yMask = 0; yMask < 16; yMask += 1) {
    const bits = {
      x: Array.from({ length: 4 }, (_, index) => (xMask >> index) & 1),
      y: Array.from({ length: 4 }, (_, index) => (yMask >> index) & 1),
    };
    assert.deepEqual(xorRepair(xorRepair(bits)), bits);
  }
}

// Independently derive the q-repair algebra from generator-value signatures.
// The number of distinct join signatures must equal the atom count of
// B_(n,max(m,n)); this does not call the encoded transition formula.
const qGeneratorSpanAuditDepth = 4;
for (let n = 0; n <= qGeneratorSpanAuditDepth; n += 1) {
  for (let m = 0; m <= qGeneratorSpanAuditDepth; m += 1) {
    const yDepth = Math.max(m, n);
    const xCount = n + 1;
    const yCount = yDepth + 1;
    const signatures = new Set();
    for (let mask = 0; mask < 2 ** (xCount + yCount); mask += 1) {
      const xBits = assignmentBits(mask, 0, xCount);
      const yBits = assignmentBits(mask, xCount, yCount);
      signatures.add(qJoinSignature(n, m, xBits, yBits));
    }
    assert.equal(signatures.size, 2 ** (xCount + yCount));
  }
}

// Exact finite certificate for the infinite-index proof: all audited contexts
// (r,0) are pairwise future-distinct under the one-bit q-defect output.
let pairCertificateCount = 0;
let maximumWitnessLength = 0;
for (let left = 0; left < 64; left += 1) {
  for (let right = left + 1; right < 64; right += 1) {
    const witness = distinguishingSuffix(left, right);
    maximumWitnessLength = Math.max(maximumWitnessLength, witness.deltaCount);
    pairCertificateCount += 1;
  }
}
assert.equal(pairCertificateCount, (64 * 63) / 2);

// Marked strict-q words alpha^r delta^s q are accepted exactly for r>s.
for (let r = 0; r <= finiteAuditDepth; r += 1) {
  for (let s = 0; s <= finiteAuditDepth; s += 1) {
    const prefix = exposeCylinderContext(r, s);
    const beforeQ = runWord(root, prefix);
    const qIsStrict = !sameContext(transition(beforeQ, "q"), beforeQ);
    assert.equal(qIsStrict, r > s);
  }
}

const sampleToleranceNumerator = 1n;
const sampleToleranceDenominator = 100000000n;
const sampleTolerance = exposeCantorPairSeriesTolerance(
  sampleToleranceNumerator,
  sampleToleranceDenominator,
);
assert(
  sampleToleranceDenominator
  < sampleToleranceNumerator * sampleTolerance.errorDenominator,
);
assert.deepEqual(
  runWord(root, sampleTolerance.word),
  context(sampleTolerance.depth, sampleTolerance.depth),
);

const report = {
  object:
    "two-axis Cantor-cylinder genesis with exact computable refinement, an involutive comparison repair, and a fixed nonpersistent defect interface",
  construction: {
    carrier: "({0,1}^N)^2 with the product topology",
    seed: "B_(0,0), generated by x_0 and y_0",
    context:
      "B_(n,m), generated by x_0,...,x_n and y_0,...,y_m",
    alpha: "D_alpha shifts the x stream and fixes y",
    delta: "D_delta shifts the y stream and fixes x",
    q: "D_q(x,y)=(x XOR y,y), an involutive homeomorphism",
    exactRepairLaw: {
      alpha: "Phi_alpha(B_(n,m))=B_(n+1,m)",
      delta: "Phi_delta(B_(n,m))=B_(n,m+1)",
      q: "Phi_q(B_(n,m))=B_(n,max(m,n))",
    },
    encodedTransitionGridCheckedThrough: finiteAuditDepth,
    xorInvolutionTruthTableCases: 16 * 16,
    qGeneratorSpanGridCheckedThrough: qGeneratorSpanAuditDepth,
  },
  externalApproximation: {
    exactFiniteCylinderExposure:
      "the ambient algebra for a task using x coordinates <=n and y coordinates <=m is available after alpha^n delta^m",
    exposureGridContextsChecked: (finiteAuditDepth + 1) ** 2,
    denseCompletion:
      "the union of B_(n,m) is the locally constant cylinder algebra, uniformly dense in C(({0,1}^N)^2)",
    sampleContinuousTarget:
      "f(x,y)=sum_i (x_i+2y_i)4^(-(i+1))",
    sampleTolerance: "1/100000000",
    exposedDepthPerStream: sampleTolerance.depth,
    exposureActionCount: sampleTolerance.word.length,
    certifiedUniformError: sampleTolerance.certifiedUniformError,
    certifiedUniformErrorApproximation:
      sampleTolerance.certifiedUniformErrorApproximation,
    readoutBoundary:
      "the exposure word reaches B_(n,m); it does not synthesize a requested element of that algebra, whose general table has 2^(n+m+2) cylinder values",
  },
  internalDefectNonsoficity: {
    canonicalDefectVector: "o_def(B_(n,m))=(1,1,1[n>m])",
    theoremInterface: "o_q(B_(n,m))=1[n>m]",
    markedStrictTraceSlice:
      "T_q intersect alpha^* delta^* q = {alpha^r delta^s q : r>s}",
    pairwiseDistinctResidualContextsChecked: 64,
    pairCertificatesChecked: pairCertificateCount,
    maximumCheckedDistinguishingSuffixLength: maximumWitnessLength,
    theorem:
      "for r<t, suffix delta^r leaves q dormant at B_(r,r) and strict at B_(t,r), so every B_(r,0) has different future q-defect behavior",
    conclusion:
      "the fixed one-bit q-defect Moore quotient has infinite index, hence no finite labeled Moore atlas realizes it",
    minimalMooreQuotient: {
      state: "d=n-m in Z",
      alpha: "d -> d+1",
      delta: "d -> d-1",
      q: "d -> min(d,0)",
      output: "1[d>0]",
      exactClassification:
        "same d gives identical futures; distinct integers are future-distinguishable, so the quotient is exactly the deterministic one-counter system Z",
    },
  },
  claimBoundary: [
    "non-sofic means infinite finite-interface Moore index, not non-soficity of a group",
    "the reachable observable-context/defect process has a short program and an exact integer-pair realization",
    "the minimal defect machine is an exact integer one-counter system, not an irrational or register-resistant state space",
    "the ordinary completed C-star algebra is not claimed to be exotic",
    "density proves universal approximation, not parameter, time, memory, or sample efficiency",
    "context exposure does not synthesize a target readout; decoder representation and cost remain external",
    "q is a batch repair, so no resource advantage is claimed without charging the declared cost model",
    "external density survives deletion of q; a strict q can accelerate finite context exposure, but no necessity theorem or costed resource advantage for defect-guided use of q is proved",
    "the knowledge ideal completes Scott-continuously, but the strict-defect output is discontinuous at the completed ideal",
  ],
};

console.log(JSON.stringify(report, null, 2));
